// Web app manifest, served at /manifest.webmanifest. Icons are generated by scripts/generate-icons.py.
// display stays "browser" for now: an installed standalone app on iOS keeps its own cookies, so a
// magic link opened from Mail would sign people in to Safari, not the app. Issue #10 decides this.
export default function manifest() {
  return {
    name: "try my thing",
    short_name: "try my thing",
    description: "Builders find real testers. Testers find new tools first.",
    start_url: "/",
    display: "browser",
    background_color: "#f7f5ef",
    theme_color: "#f7f5ef",
    icons: [
      { src: "/icons/icon-192.png", sizes: "192x192", type: "image/png", purpose: "any" },
      { src: "/icons/icon-512.png", sizes: "512x512", type: "image/png", purpose: "any" },
      { src: "/icons/icon-maskable-512.png", sizes: "512x512", type: "image/png", purpose: "maskable" },
    ],
  };
}
